// Problem: Find two numbers in an array that sum to a target
// Narration: "My first instinct is to use a HashMap to store complements."

public Optional<int[]> findTwoSum(int[] nums, int target) {
    // "I'm creating a map to track numbers I've seen so far"
    var seen = new HashMap<Integer, Integer>();

    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];

        // "At each element, I check if its complement exists"
        if (seen.containsKey(complement)) {
            // "The trade-off here is O(n) space for O(n) time"
            return Optional.of(new int[]{seen.get(complement), i});
        }

        // "I'm storing the index so I can return both positions"
        seen.put(nums[i], i);
    }

    return Optional.empty();
}

// Plain English: "We'll track seen numbers in a set. Loop through the array.
//                If we've seen this number before, return it. Otherwise, add it."

public Optional<Integer> findFirstDuplicate(int[] numbers) {
    // "Create a set to remember numbers we've seen"
    var seen = new HashSet<Integer>();

    // "Loop through each number in the array"
    for (int num : numbers) {
        // "Check if we've seen this number before"
        if (seen.contains(num)) {
            // "If yes, we found the duplicate"
            return Optional.of(num);
        }
        // "Otherwise, remember this number for later"
        seen.add(num);
    }

    // "If we finish the loop, no duplicates exist"
    return Optional.empty();
}

// Bug: This code tries to find duplicates but always returns empty
// Narration: "Let me trace through with input [1, 2, 3, 2]"

public Optional<Integer> findDuplicateBuggy(int[] numbers) {
    var seen = new HashSet<Integer>();

    for (int num : numbers) {
        // "At num = 1: seen is empty, so contains returns false. We add 1."
        // "At num = 2: seen has {1}, contains returns false. We add 2."
        // "At num = 3: seen has {1, 2}, contains returns false. We add 3."
        // "At num = 2 (second occurrence): seen has {1, 2, 3}, contains should return true!"
        if (seen.contains(num)) {
            return Optional.of(num);
        }
        seen.add(num);
    }
    // "Wait, I expected to return 2, but we're returning empty."
    // "Ah! The bug is I'm checking membership before adding. The first 2 gets added,
    //  so when we see the second 2, contains returns true. This should work."
    // "Let me re-trace... Oh! I see it now. Logic is correct. Must be a test case issue."
    return Optional.empty();
}

// Narration: "Let me walk through the time complexity."

public boolean hasDuplicate(int[] numbers) {
    var seen = new HashSet<Integer>();

    // "This loop is the bottleneck. It runs once for each element, so n times."
    for (int num : numbers) {
        // "Inside, this contains check is O(1) on average for HashSet."
        if (seen.contains(num)) {
            return true;
        }
        // "And this add operation is also O(1) on average."
        seen.add(num);
    }

    // "So overall, we do O(1) work n times, which gives us O(n) time complexity."
    // "Space complexity is also O(n) because in the worst case — no duplicates —
    //  we store all n elements in the set."
    return false;
}
